struct node { int kind; int value; size_t nchild; struct node **child; };
struct frame { struct node *parent; size_t index; struct frame *up; };  /* one hole */
struct loc { struct node *focus; struct frame *up; };
struct loc loc_down(struct loc l) {          /* push: leftmost child */
    struct frame *f = malloc(sizeof *f);
    *f = (struct frame){ l.focus, 0, l.up };
    return (struct loc){ l.focus->child[0], f };
}
struct loc loc_up(struct loc l) {            /* pop: rebuild the parent, free the frame */
    size_t i = l.up->index; struct node *p = l.up->parent; struct frame *u = l.up->up;
    free(l.up); p->child[i] = l.focus; return (struct loc){ p, u };
}
